-- Origin SQL:
SELECT a FROM ((SELECT 1 AS a) UNION ALL (SELECT 2 AS a));
SELECT a FROM ((SELECT 1 AS a) UNION DISTINCT SELECT 2 AS a);
SELECT a FROM ((SELECT 1 AS a) EXCEPT (SELECT 2 AS a));
SELECT a FROM ((SELECT 1 AS a) INTERSECT (SELECT 2 AS a));
(SELECT 1 AS a) UNION ALL SELECT 2 AS a;
(SELECT 1 UNION ALL SELECT 2) UNION ALL SELECT 3;
SELECT 1 UNION ALL (SELECT 2) UNION ALL SELECT 3;
SELECT a FROM (((SELECT 1 AS a)));
(SELECT 1 UNION ALL SELECT 2) INTERSECT SELECT 2;
SELECT 1 INTERSECT (SELECT 2 UNION ALL SELECT 1);
(SELECT 1) SETTINGS max_threads=1;
(SELECT 1 UNION ALL SELECT 2) SETTINGS max_threads=1 FORMAT JSONEachRow;


